function wallClock(epochMs: number, timeZone: string): WallClock {
  const parts: Record<string, string> = {};
  for (const part of wallClockFormatter(timeZone).formatToParts(new Date(epochMs))) {
    parts[part.type] = part.value;
  }
  const rawYear = Number(parts.year);
  const year = parts.era === "BC" || parts.era === "B" ? 1 - rawYear : rawYear;
  return {
    year,
    month: Number(parts.month),
    day: Number(parts.day),
    hour: Number(parts.hour) % 24,
    minute: Number(parts.minute),
    second: Number(parts.second),
  };
}

function wallAsUtcMs(wall: WallClock): number {
  const date = new Date(0);
  date.setUTCFullYear(wall.year, wall.month - 1, wall.day);
  date.setUTCHours(wall.hour, wall.minute, wall.second, 0);
  return date.getTime();
}

/** Offset of the zone from UTC at `epochMs`, in milliseconds. */
function zoneOffsetMs(epochMs: number, timeZone: string): number {
  const wholeSecond = Math.floor(epochMs / 1000) * 1000;
  return wallAsUtcMs(wallClock(wholeSecond, timeZone)) - wholeSecond;
}

/**
 * The instant at which the zone's clock reads the given wall time. A time
 * that happens twice (clocks going back) resolves to the earlier instant; a
 * time that never happens (clocks going forward) resolves to the moment the
 * clock jumped past it.
 */
function wallToInstantMs(
  year: number,
  month: number,
  day: number,
  hour: number,
  timeZone: string,
): number {
  const wall = Date.UTC(year, month - 1, day, hour, 0, 0, 0);
  const before = zoneOffsetMs(wall - DAY_MS, timeZone);
  const after = zoneOffsetMs(wall + DAY_MS, timeZone);

  const candidates = [wall - before, wall - after].filter(
    (instant) => instant + zoneOffsetMs(instant, timeZone) === wall,
  );
  if (candidates.length > 0) return Math.min(...candidates);

  // The wall time falls in a gap: the clock jumped from before the gap
  // straight past it at the instant `wall - before` names.
  return wall - before;
}

function pad(value: number, width = 2): string {
  return String(value).padStart(width, "0");
}

/** `YYYY-MM-DD` calendar date of the instant on the zone's clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const wall = wallClock(parseIso(value).getTime(), timeZone);
  return `${pad(wall.year, 4)}-${pad(wall.month)}-${pad(wall.day)}`;
}

/**
 * The UTC instant at which the zone's calendar day containing `reference`
 * began.
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const wall = wallClock(reference.getTime(), timeZone);
  return toIsoTimestamp(
    new Date(wallToInstantMs(wall.year, wall.month, wall.day, 0, timeZone)),
  );
