export function startOfLocalDayOffset(
  reference: Date,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const wall = wallClock(reference.getTime(), timeZone);
  const shifted = new Date(Date.UTC(wall.year, wall.month - 1, wall.day + days));
  return toIsoTimestamp(
    new Date(
      wallToInstantMs(
        shifted.getUTCFullYear(),
        shifted.getUTCMonth() + 1,
        shifted.getUTCDate(),
