 * workspace clock) containing `dueAt` has ended — i.e. once `reference` falls
 * on a later local date.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  const dayStart = parseIso(startOfLocalDay(reference, timeZone)).getTime();
  return parseIso(dueAt).getTime() < dayStart;
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The window a digest covers, ending at the most recent local `digestHour:00`
 * at or before `reference` on the zone's clock — today's if it has passed,
 * yesterday's otherwise — and starting at the same local hour on the previous
 * calendar day (23 or 25 hours across a DST change).
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHour must be 0-23, got ${digestHour}`);
  }

  const wall = wallClock(reference.getTime(), timeZone);
  const atLocalHour = (dayOffset: number): number => {
    const day = new Date(Date.UTC(wall.year, wall.month - 1, wall.day + dayOffset));
    return wallToInstantMs(
      day.getUTCFullYear(),
      day.getUTCMonth() + 1,
      day.getUTCDate(),
      digestHour,
      timeZone,
    );
  };

  let endOffset = 0;
  let end = atLocalHour(0);
  if (end > reference.getTime()) {
    endOffset = -1;
    end = atLocalHour(-1);
  }
  const start = atLocalHour(endOffset - 1);

  return {
    start: toIsoTimestamp(new Date(start)),
    end: toIsoTimestamp(new Date(end)),
  };
}
